// devices.platform.syncZones — E4, Vlad 4 Nov (names and categories follow the platform). Generated by
// `pnpm gen:command`; guard cases kept, acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, runAsOwner, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  NotFound,
  openTestKernel,
  systemActor,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { syncZones } from '../commands/sync-zones.ts';

const sync = systemActor('device-platform');
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
let siteB: string;
const zones = (where: string) => countRows(testDb.url, `zone WHERE ${where}`);
const run = (input: Record<string, unknown>) =>
  t.kernel.execute(syncZones, sync, { siteId: siteA, ...input }, 'system');

const store = { ref: 'area-1', kind: 'area', name: 'Store A1' };
const gate = { ref: 'gate-1', kind: 'gate', name: 'Gate 1', entrance: true };
const storeGate = { ref: 'gate-2', kind: 'gate', name: 'Store A1 door' };

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(sync, syncZones.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  ({ id: siteB } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  // No command links a project to its mall yet; set it up directly.
  await runAsOwner(testDb.url, `UPDATE site SET platform_ref = 'mall-a' WHERE id = $1`, [siteA]);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('devices.platform.syncZones', () => {
  it('refuses anyone but the system actor, a bad snapshot, and a project without a mall', async () => {
    await expect(
      t.kernel.execute(syncZones, aStaffActor(), { siteId: siteA, zones: [] }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
    await expect(run({ zones: [store, store] })).rejects.toBeInstanceOf(ValidationFailed);
    await expect(run({ zones: [{ ...store, kind: 'floor' }] })).rejects.toBeInstanceOf(ValidationFailed);
    await expect(run({ siteId: randomUUID(), zones: [] })).rejects.toBeInstanceOf(NotFound);
    await expect(run({ siteId: siteB, zones: [] })).rejects.toBeInstanceOf(Conflict);
  });

  it('first sync adds the stores and gates; only a gate can be an entrance', async () => {
    expect(
      await run({ zones: [store, gate, storeGate, { ...store, ref: 'area-2', entrance: true }] }),
    ).toEqual({
      added: ['area-1', 'gate-1', 'gate-2', 'area-2'],
      changed: [],
      archived: [],
    });
    expect(await zones(`entrance`)).toBe(1);
  });

  it('the same snapshot again changes nothing (idempotent)', async () => {
    const again = await run({ zones: [store, gate, storeGate, { ...store, ref: 'area-2' }] });
    expect(again).toEqual({ added: [], changed: [], archived: [] });
  });

  it('renames and entrance-type changes on the platform are taken over; a zone gone is archived', async () => {
    const r = await run({
      zones: [
        { ...store, name: 'Store A1 (new tenant)' },
        { ...gate, entrance: false },
        { ...storeGate, entrance: true },
      ],
    });
    expect(r.changed).toEqual([
      { ref: 'area-1', from: 'Store A1 (area)', to: 'Store A1 (new tenant) (area)' },
      { ref: 'gate-1', from: 'Gate 1 (gate, entrance)', to: 'Gate 1 (gate)' },
      { ref: 'gate-2', from: 'Store A1 door (gate)', to: 'Store A1 door (gate, entrance)' },
    ]);
    expect(r.archived).toEqual(['area-2']);
    expect(await zones(`name = 'Store A1 (new tenant)' AND archived_at IS NULL`)).toBe(1);
    expect(await zones(`platform_ref = 'area-2' AND archived_at IS NOT NULL`)).toBe(1);
  });

  it('a zone that comes back after being archived is added again', async () => {
    const r = await run({ zones: [store, gate, storeGate, { ...store, ref: 'area-2', name: 'Store A2' }] });
    expect(r.added).toEqual(['area-2']);
    expect(await zones(`platform_ref = 'area-2'`)).toBe(2);
  });
});
